* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--fg); font: var(--weight-normal) var(--fs-body)/var(--leading) var(--font); }
button, input, a { -webkit-tap-highlight-color: transparent; }
button, input { font: inherit; }
button, a { touch-action: manipulation; }
button { cursor: pointer; }
button, a, input { scroll-margin-block: var(--s6); }
:focus-visible { outline: var(--focus-width) solid var(--focus); outline-offset: var(--focus-offset); }
h1:focus, h2:focus { outline: none; }
#app { max-width: var(--page-width); min-height: 100vh; min-height: 100svh; margin-inline: auto; display: flex; flex-direction: column; }
.masthead { min-height: var(--s10); padding: var(--s4) var(--gutter) var(--s2); display: flex; align-items: center; justify-content: space-between; gap: var(--s3); }
.brand { display: flex; align-items: center; gap: var(--s2); font-size: var(--fs-brand); font-weight: var(--weight-bold); letter-spacing: -.035em; }
.brand-mark { width: var(--mark-size); height: var(--mark-size); color: var(--action); }
.utility { background: transparent; border: 0; color: var(--action); padding: var(--s2); min-height: var(--target); min-width: var(--target); text-decoration: underline; text-underline-offset: var(--s1); font-weight: var(--weight-medium); }
main { padding: var(--s2) var(--gutter) var(--s6); flex: 1; display: flex; flex-direction: column; }
.topline { display: flex; align-items: center; justify-content: space-between; gap: var(--s2); margin-bottom: var(--s5); }
.back { display: inline-flex; gap: var(--s2); align-items: center; padding-left: 0; text-decoration: none; }
.back svg { width: var(--icon-size); height: var(--icon-size); }
.step { font-size: var(--fs-small); color: var(--muted); }
.eyebrow { font-size: var(--fs-small); color: var(--muted); letter-spacing: var(--label-spacing); font-weight: var(--weight-medium); margin: 0 0 var(--s4); }
h1, h2, p { margin: 0; }
h1, h2 { line-height: var(--leading-heading); font-weight: var(--weight-bold); letter-spacing: -.025em; }
h1 { font-size: var(--fs-heading); margin-bottom: var(--s4); }
h2 { font-size: var(--fs-heading); }
.intro { color: var(--muted); margin-bottom: var(--s6); }
.welcome { padding-top: var(--s7); }
.welcome h1 { font-size: var(--fs-hero); max-width: 100%; margin-bottom: var(--s5); }
.welcome .intro { margin-bottom: var(--s7); }
.journey { list-style: none; margin: 0 0 var(--s7); padding: 0; }
.journey li { display: grid; grid-template-columns: var(--s8) 1fr; gap: var(--s4); position: relative; padding-bottom: var(--s6); }
.journey li:last-child { padding-bottom: 0; }
.journey li:not(:last-child)::before { content: ''; position: absolute; top: var(--s8); bottom: 0; left: var(--s5); border-left: var(--stroke) solid var(--line); }
.number { width: var(--s8); height: var(--s8); display: grid; place-items: center; border: var(--stroke) solid var(--line); border-radius: var(--round); font-size: var(--fs-body); font-weight: var(--weight-medium); color: var(--action); }
.journey strong { display: block; font-size: var(--fs-label); font-weight: var(--weight-medium); }
.journey p { color: var(--muted); font-size: var(--fs-small); margin-top: var(--s1); }
.actions { margin-top: auto; padding-top: var(--s6); }
.primary, .secondary { width: 100%; min-height: var(--input-height); display: flex; align-items: center; justify-content: center; gap: var(--s3); border-radius: var(--radius); padding: var(--s3) var(--s4); font-size: var(--fs-label); font-weight: var(--weight-medium); text-decoration: none; }
.primary { border: var(--stroke-strong) solid var(--action); background: var(--action); color: var(--on-action); }
.primary:hover { text-decoration: underline; text-underline-offset: var(--s1); }
.primary:active { transform: translateY(var(--stroke)); }
.secondary { background: transparent; color: var(--action); border: var(--stroke) solid var(--input-line); }
.fine { font-size: var(--fs-small); color: var(--muted); }
.disclosure { text-align: center; margin-top: var(--s4); }
.reassurance { text-align: center; margin-top: var(--s5); }
.reassurance a { color: var(--action); }
.field { margin-bottom: var(--s6); }
label { display: block; font-size: var(--fs-label); font-weight: var(--weight-medium); margin-bottom: var(--s2); }
.hint { font-size: var(--fs-small); color: var(--muted); margin-bottom: var(--s2); }
input { display: block; width: 100%; min-height: var(--input-height); border: var(--stroke) solid var(--input-line); border-radius: var(--radius); padding: var(--s3) var(--s4); background: var(--surface); color: var(--fg); font-size: var(--fs-label); }
input[aria-invalid="true"] { border: var(--stroke-strong) solid var(--error); }
.error { color: var(--error); font-size: var(--fs-body); margin-top: var(--s2); }
.error:empty { display: none; }
form { display: flex; flex: 1; flex-direction: column; }
.notice { border-left: var(--stroke-strong) solid var(--action); padding: var(--s3) var(--s4); background: var(--tint); font-size: var(--fs-body); margin-top: var(--s2); }
.notice strong { display: block; margin-bottom: var(--s1); font-weight: var(--weight-bold); }
.code-input { font-family: var(--mono); font-size: var(--fs-code); letter-spacing: var(--code-spacing); }
.inline-action { text-align: left; padding-left: 0; display: inline-block; margin-top: var(--s2); }
.prototype { margin-top: var(--s5); }
.success-mark { width: var(--s10); height: var(--s10); display: grid; place-items: center; border: var(--stroke) solid var(--line); background: var(--tint); color: var(--action); border-radius: var(--round); margin: var(--s5) 0 var(--s6); }
.success-mark svg { width: var(--s7); height: var(--s7); }
.account { border: var(--stroke) solid var(--line); border-radius: var(--radius-card); margin: var(--s2) 0 var(--s6); background: var(--surface); overflow: hidden; }
.account-heading { padding: var(--s5); background: var(--tint); border-bottom: var(--stroke) solid var(--line); }
.account-heading strong { display: block; font-size: var(--fs-label); font-weight: var(--weight-medium); }
.account dl { padding: var(--s5); margin: 0; }
.account dl div + div { margin-top: var(--s4); }
.account dt { font-size: var(--fs-small); color: var(--muted); }
.account dd { margin: var(--s1) 0 0; font-size: var(--fs-label); font-variant-numeric: tabular-nums; }
.account .balance { font-size: var(--fs-heading); font-weight: var(--weight-medium); }
dialog { max-width: min(var(--dialog-width), calc(100% - var(--s6))); max-height: calc(100svh - var(--s6)); margin: auto; padding: var(--s6); background: var(--bg); color: var(--fg); border: var(--stroke) solid var(--line); border-radius: var(--radius-card); box-shadow: var(--shadow); overflow-y: auto; }
dialog::backdrop { background: var(--scrim); }
.dialog-top { display: flex; justify-content: space-between; align-items: center; gap: var(--s2); margin-bottom: var(--s5); }
.dialog-top .eyebrow { margin: 0; }
.dialog-top .utility { padding-right: 0; }
dialog h2 { margin-bottom: var(--s4); }
dialog .primary { margin-block: var(--s6) var(--s3); flex-direction: column; gap: 0; }
.phone { letter-spacing: var(--phone-spacing); white-space: nowrap; }
dialog .secondary { margin-top: var(--s6); }
.sr-only { position: absolute; width: var(--stroke); height: var(--stroke); padding: 0; margin: calc(-1 * var(--stroke)); overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; animation: none !important; } }
