:root {
  color-scheme: light;
  --bg: #f8f7f2;
  --surface: #ffffff;
  --fg: #1b3038;
  --muted: #52616a;
  --action: #155361;
  --on-action: #ffffff;
  --tint: #e8eeeb;
  --line: #c8d1cf;
  --input-line: #738486;
  --error: #a02f28;
  --error-bg: #fff0ec;
  --focus: #9b4d00;
  --scrim: #142e38b8;
  --shadow: 0 8px 40px #102b3826;
  --font: 'IBM Plex Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --mono: 'IBM Plex Mono', monospace;
  --fs-small: 1rem;
  --fs-body: 1.125rem;
  --fs-label: 1.25rem;
  --fs-brand: 1.625rem;
  --fs-heading: 2rem;
  --fs-hero: 2.5rem;
  --fs-code: 2rem;
  --leading: 1.5;
  --leading-heading: 1.15;
  --weight-normal: 400;
  --weight-medium: 500;
  --weight-bold: 600;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 20px;
  --s6: 24px;
  --s7: 32px;
  --s8: 40px;
  --s9: 48px;
  --s10: 64px;
  --gutter: 24px;
  --target: 52px;
  --input-height: 60px;
  --radius: 8px;
  --radius-card: 12px;
  --stroke: 1px;
  --stroke-strong: 2px;
  --focus-width: 3px;
  --focus-offset: 4px;
  --page-width: 440px;
  --dialog-width: 440px;
  --mark-size: 32px;
  --icon-size: 22px;
  --round: 50%;
  --code-spacing: .22em;
  --label-spacing: .09em;
  --phone-spacing: .01em;
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #14272d;
  --surface: #1c333a;
  --fg: #f5f5ed;
  --muted: #b8c8ca;
  --action: #b6dedc;
  --on-action: #12343c;
  --tint: #223e44;
  --line: #47616a;
  --input-line: #849b9f;
  --error: #ffb3a5;
  --error-bg: #432d2d;
  --focus: #f7c78a;
  --scrim: #050e15c9;
  --shadow: 0 8px 40px #00000040;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --bg: #14272d;
    --surface: #1c333a;
    --fg: #f5f5ed;
    --muted: #b8c8ca;
    --action: #b6dedc;
    --on-action: #12343c;
    --tint: #223e44;
    --line: #47616a;
    --input-line: #849b9f;
    --error: #ffb3a5;
    --error-bg: #432d2d;
    --focus: #f7c78a;
    --scrim: #050e15c9;
    --shadow: 0 8px 40px #00000040;
  }
}
@media (max-width: 350px) {
  :root { --gutter: 20px; --fs-hero: 2.125rem; }
}

